def shell(title,description,body,base='./',active='',path=''):
 support_assets='<link rel="stylesheet" href="support.css?v=readability-v5-20261109"><script src="support.js?v=20261108" defer></script>' if path=='support/' else ''
 structured={'@context':'https://schema.org','@type':'SoftwareApplication'if not path else'WebPage','name':'GØ-404'if not path else title,'description':description,'inLanguage':'en-US'}
