 return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#080808"><meta name="description" content="{esc(description)}"><meta name="robots" content="{'noindex, nofollow'if C['preview']else'index, follow'}"><title>{esc(title)}</title><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:site_name" content="GØ-404"><meta property="og:locale" content="en_US">{canonical}<link rel="icon" href="{base}assets/favicon.png" type="image/png"><link rel="preload" href="{base}assets/fonts/BarlowCondensed-Bold.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="{base}assets/site.css?v=raised-creases-v8-20261111"><script src="{base}assets/site.js" defer></script>{support_assets}<script type="application/ld+json">{data}</script></head><body>{header(base,active)}{body}{footer(base)}<dialog class="image-dialog" aria-label="GØ-404 interface detail"><button class="dialog-close" aria-label="Close image">CLOSE ×</button><img alt=""></dialog></body></html>'''
